import storage
import copy

def test_upgrade_v1_to_v2():
    v1_yes = {"id": 1, "name": "Alice", "remote": "yes"}
    v2_expected = {"version": 2, "id": 1, "title": "Alice", "work_mode": "remote"}

    res = models.upgrade(copy.deepcopy(v1_yes))
    assert res == v2_expected
    assert v1_yes == {"id": 1, "name": "Alice", "remote": "yes"}, "Input should not be modified"

    v1_no = {"id": 2, "name": "Bob", "remote": "no"}
    v2_expected_no = {"version": 2, "id": 2, "title": "Bob", "work_mode": "office"}
    res = models.upgrade(copy.deepcopy(v1_no))
    assert res == v2_expected_no

    v1_missing = {"id": 3, "name": "Charlie"}
    v2_expected_missing = {"version": 2, "id": 3, "title": "Charlie", "work_mode": "unknown"}
    res = models.upgrade(copy.deepcopy(v1_missing))
    assert res == v2_expected_missing

    v1_invalid = {"id": 4, "name": "Dave", "remote": "maybe"}
    try:
        models.upgrade(v1_invalid)
        assert False, "Should raise ValueError for invalid remote value"
    except ValueError:
        pass

    v1_invalid_missing_name = {"id": 5, "remote": "yes"}
    try:
        models.upgrade(v1_invalid_missing_name)
        assert False, "Should raise KeyError if name is missing (implied by pop)"
    except KeyError:
        pass

    # Idempotency for v2
    v2 = {"version": 2, "id": 6, "title": "Eve", "work_mode": "remote"}
    res = models.upgrade(copy.deepcopy(v2))
    assert res == v2
    assert v2 == {"version": 2, "id": 6, "title": "Eve", "work_mode": "remote"}, "Input should not be modified"

def test_storage():
    # Mixed v1/v2 input for load_all
    v1 = {"id": 1, "name": "Alice", "remote": "yes"}
    v2 = {"version": 2, "id": 2, "title": "Bob", "work_mode": "office"}
    rows = [v1, v2]

    loaded = storage.load_all(rows)
    assert len(loaded) == 2
    assert loaded[0] == {"version": 2, "id": 1, "title": "Alice", "work_mode": "remote"}
    assert loaded[1] == {"version": 2, "id": 2, "title": "Bob", "work_mode": "office"}

    # Save must always return v2
    v1_for_save = {"id": 3, "name": "Charlie", "remote": "no"}
    saved = storage.save(v1_for_save)
    assert saved["version"] == 2
    assert saved["work_mode"] == "office"
    assert "name" not in saved
    assert "remote" not in saved
    assert "title" in saved

if __name__ == "__main__":
    test_upgrade_v1_to_v2()
    test_storage()
    print("All tests passed!")
